//! Embedded assets: the OpenAPI document (generated by
//! protoc-gen-openapi) rides the binary — a build artifact of the
//! contract tree, not an operator-editable config, and embedded exactly
//! like the reference's `go:embed` of the same file. The runtime
//! configuration yamls live on disk instead (`configs/`, resolved by
//! [`crate::admin::config::config_dir`]).

/// The protoc-gen-openapi output for the full admin contract.
pub const OPENAPI_DATA: &str = include_str!("../../assets/openapi.yaml");
